fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    // Choose a split point at the midpoint.
    // This ensures that for any input of length > 1,
    // both resulting vectors are strictly shorter than the original.
    let mid = a.len() / 2;

    // `split_off` will take all elements from `mid` to the end
    // and return them as a new Vec, leaving the first `mid` elements
    // in the original Vec.
    let mut first = a;
    let second = first.split_off(mid);

    (first, second)
}

